package com.fiap.sast.rules;
import com.fiap.sast.analysis.SecurityFinding; import com.github.javaparser.ast.CompilationUnit; import com.github.javaparser.ast.expr.*; import org.springframework.stereotype.Component; import java.util.*;
@Component public class HardcodedCredentialRule implements SecurityRule { public String ruleId(){return "SAST-JAVA-001";} private boolean name(String n){return n.toLowerCase().matches(".*(password|passwd|pwd|secret|apikey|token).*");} private SecurityFinding f(String file,String s,com.github.javaparser.ast.Node n){return RuleSupport.finding(ruleId(),"Hardcoded credential","Critical","CWE-798","Credencial armazenada diretamente no código-fonte.",file,s,n);} public List<SecurityFinding> analyze(CompilationUnit a,String s,String file){var out=new ArrayList<SecurityFinding>(); a.findAll(com.github.javaparser.ast.body.VariableDeclarator.class).forEach(v->{if(name(v.getNameAsString())&&v.getInitializer().filter(x->x.isStringLiteralExpr()&&!x.asStringLiteralExpr().asString().isEmpty()).isPresent())out.add(f(file,s,v));}); a.findAll(AssignExpr.class).forEach(x->{String n=x.getTarget().toString(); if(name(n)&&x.getValue().isStringLiteralExpr()&&!x.getValue().asStringLiteralExpr().asString().isEmpty())out.add(f(file,s,x));}); return out;} }
